 * Parses the build-graph text format into a map of task name to
 * `{ cost, deps }`, where `deps` is a `Set` of the names it depends on.
 */

import { CliError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const depDirectives = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`line ${lineNo}: expected task <name> <cost>`)
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`line ${lineNo}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new CliError(`line ${lineNo}: task ${name} is declared twice`)
      }
      tasks.set(name, { cost: parseInt(costStr, 10), deps: new Set() })
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const [, name, ...deps] = words
      depDirectives.push({ name, deps })
    } else {
      throw new CliError(`line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const { name, deps } of depDirectives) {
    if (!tasks.has(name)) throw new CliError(`unknown task ${name}`)
    for (const dep of deps) {
      if (!tasks.has(dep)) throw new CliError(`unknown task ${dep}`)
    }
  }

  for (const { name, deps } of depDirectives) {
    const task = tasks.get(name)
    for (const dep of deps) task.deps.add(dep)
  }

  return tasks
}
"}

