 * Computations over a validated task graph: cycle detection, the
 * unlimited-worker schedule (start/finish/depth per task), and the
 * priority used to break ties when packing tasks onto a fixed number of
 * workers.
 */

import { CycleError } from './errors.js'

/**
 * Depth-first search from each task in ascending name order, walking each
 * task's dependencies in ascending name order. Throws `CycleError` for the
 * first cycle such a search re-enters.
 */
export function checkForCycle(tasks) {
  const names = [...tasks.keys()].sort()
  const state = new Map(names.map((name) => [name, 'unvisited']))
  const stack = []

  function visit(name) {
    state.set(name, 'active')
    stack.push(name)
    const deps = [...tasks.get(name).deps].sort()
    for (const dep of deps) {
      const depState = state.get(dep)
      if (depState === 'active') {
        const start = stack.indexOf(dep)
        throw new CycleError([...stack.slice(start), dep])
      }
      if (depState === 'unvisited') visit(dep)
    }
    stack.pop()
    state.set(name, 'done')
  }

  for (const name of names) {
    if (state.get(name) === 'unvisited') visit(name)
  }
}

/**
 * Computes, for every task, its depth (the wave it sits in), start and
 * finish under unlimited workers. A task's start is the greatest finish
 * among its dependencies, or 0 when it has none.
 */
export function computeSchedule(tasks) {
  const result = new Map()

  function compute(name) {
    if (result.has(name)) return result.get(name)
    const task = tasks.get(name)
    let depth = 0
    let start = 0
    for (const dep of task.deps) {
      const depResult = compute(dep)
      depth = Math.max(depth, depResult.depth + 1)
      start = Math.max(start, depResult.finish)
    }
    const finish = start + task.cost
    const entry = { start, finish, depth }
    result.set(name, entry)
    return entry
  }

  for (const name of tasks.keys()) compute(name)
  return result
}

/**
 * The cost of the longest chain of dependents beginning at each task,
 * counting its own cost and continuing down to a task nothing depends on.
 */
export function computePriority(tasks) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, task] of tasks) {
    for (const dep of task.deps) dependents.get(dep).push(name)
  }

  const priority = new Map()

  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    const task = tasks.get(name)
    let downstream = 0
    for (const dependent of dependents.get(name)) {
      downstream = Math.max(downstream, compute(dependent))
    }
    const value = task.cost + downstream
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) compute(name)
  return priority
}
"}

