 * Simulates the build graph running on a fixed number of workers, greedily
 * starting the highest-priority ready task on the lowest-index free worker
 * at every instant.
 */

import { computePriority } from './graph.js'

export function pack(tasks, workerCount) {
  const priority = computePriority(tasks)
  const remaining = new Set(tasks.keys())
  const finishTime = new Map()
  const workerFreeAt = new Array(workerCount).fill(0)
  const workerLog = Array.from({ length: workerCount }, () => [])

  let time = 0
  while (remaining.size > 0) {
    let assigned = true
    while (assigned) {
      assigned = false

      let workerIndex = -1
      for (let i = 0; i < workerCount; i++) {
        if (workerFreeAt[i] <= time) {
          workerIndex = i
          break
        }
      }
